 if m.sum()<10:continue
 S=thin(m); y0,x0=sl[0].start,sl[1].start
 pix={ (int(y+y0),int(x+x0)) for y,x in zip(*np.where(S)) }
 G={p:[] for p in pix}
 for y,x in pix:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not dx and not dy:continue
    z=(y+dy,x+dx)
    if z not in pix:continue
    if dx and dy and (((y,x+dx) in pix) or ((y+dy,x) in pix)):continue
    G[(y,x)].append(z)
 deg={p:len(v) for p,v in G.items()}
 # connected comp
 seen=set();cc=0
 for p in pix:
  if p in seen:continue
