  while stack:
   u=stack.pop()
   for v in G[u]:
    if v not in seen:seen.add(v);stack.append(v)
 def dijkstra(src):
  d={src:0.};pr={};hp=[(0.,src)]
  while hp:
   du,u=heapq.heappop(hp)
   if du!=d[u]:continue
   for v in G[u]:
    nd=du+math.hypot(v[0]-u[0],v[1]-u[1])
    if nd<d.get(v,1e9):d[v]=nd;pr[v]=u;heapq.heappush(hp,(nd,v))
  return d,pr
 ends=[p for p in G if deg[p]==1]
 print('\nCOMP',cid,'bbox',sl,'n',len(pix),'cc',cc,'deg histogram', {k:list(deg.values()).count(k) for k in set(deg.values())},'ends',ends)
 if len(ends)>=2:
  best=None
  for s in ends:
   d,pr=dijkstra(s)
   for e in ends:
    if e!=s and (best is None or d[e]>best[0]):best=(d[e],s,e)
  print('farthest ends',best)
 if all(deg[p]==2 for p in G): print('cycle')
