def interp(a,b,t): return gen.quat_slerp_wxyz(a,b,t)
def step_to(target,maxpos=.008,maxang=.2):
 global q,cur,mm,maxdq,count
 target=np.asarray(target,float);dpos=float(np.linalg.norm(target[:3]-cur[:3]));dang=2*math.acos(np.clip(abs(float(cur[3:]@target[3:])),0,1));n=max(1,math.ceil(dpos/maxpos),math.ceil(dang/maxang))
