  if not a.get('ok'):raise RuntimeError(f'IK fail step {count} at {np.round(po,5)} err={a.get("error")} q7={q[6]:.3f}')
  nq=np.asarray(a['q'],float);maxdq=max(maxdq,float(np.linalg.norm(nq-q)));mm=min(mm,float(np.min(np.r_[nq-lo,hi-nq])));q=nq;cur=po;count+=1

