 out.append(np.r_[gen.FAR_X-(p[-1,1]+.5)*gen.PX_MM/1000,gen.LEFT_Y-(p[-1,0]+.5)*gen.PX_MM/1000,gen.INK_Z,qs[-1]])
 return np.asarray(out,np.float32)

def endpoint_options(name):
 items=gen.build_paths()[1];fields=gen.build_paths()[2];p=gen.correction_routes(items)[0 if name.startswith('m') else 1][1];item=gen.item_for(name,items);field=fields[items.index(item)];opts=[]
 for side in [1.,-1.]:
  pose=gen.poses_for_path(p,name,item,field,width_multiplier=.8,axis_tangent=True,heading_smooth_px=4,side=side)[0][-1]
